// ReverseIntSlice reverses a slice of integers in place.
func ReverseIntSlice(slice []int) {
    // Initialize two pointers: one at the beginning (i) and one at the end (j).
    left := 0
    right := len(slice) - 1

    // Continue swapping elements until the pointers meet or cross each other.
    for left < right {
        // 1. Swap the elements at the left and right indices
        slice[left], slice[right] = slice[right], slice[left]

        // 2. Move the pointers inward
        left++
        right--
    }
}

